mapper.select:
SELECT T.INSTRUMENT_ID AS DEALID, T.COUNTERPARTY_CODE, T.COUNTERPARTY_CODE AS COUNTERPARTY_NAME, T.CURRENCY_PAIR AS HEDGING_SET, '外汇远期' AS TRADE_TYPE,
T.BUY_OR_SELL AS POSITION, T.TRADE_DATE AS START_DATE, T.SETTLE_DATE AS END_DATE, T.UNDERLYING_CURRENCY_CODE, T.UNDERLYING_CURRENCY_NOTIONAL,
T.BASE_CURRENCY_CODE, T.BASE_CURRENCY_NOTIONAL, T1.NPV_CNY AS MTM, 'CNY' AS MTM_CCY, NULL AS STRIKE_PRICE, NULL AS UNDERLYING_PRICE, T2.MA_ID
FROM TB_13_FX_FORWARD_ALL T
LEFT JOIN TB_26_TRADE_MEASURE T1 ON T.INSTRUMENT_ID = T1.INSTRUMENT_ID AND T1.DATA_DATE = #{dataDate,jdbcType=DATE}
LEFT JOIN TB_17_SACCR_MA_CSA T2 ON T2.COUNTERPARTY_CODE = T.COUNTERPARTY_CODE AND T2.DATA_DATE = #{dataDate,jdbcType=DATE}
WHERE T.SETTLE_DATE  > #{dataDate,jdbcType=DATE}
AND T.INSTRUMENT_ID NOT IN (SELECT INSTRUMENT_ID FROM	TB_13_FX_SPOT_ALL WHERE	DATA_DATE = #{dataDate,jdbcType=DATE})

SELECT T.INSTRUMENT_ID AS DEALID, T.COUNTERPARTY_CODE, T.COUNTERPARTY_CODE AS COUNTERPARTY_NAME, T.START_DATE, T.MATURITY_DATE AS END_DATE,
T.BUY_OR_SELL AS POSITION, '信用违约互换' AS TRADE_TYPE, NULL AS CALL_PUT_FLAG, NULL AS STRIKE_PRICE, NULL AS UNDERLYING_PRICE, T.UNDERLYING_BOND_ID AS HEDGING_SET,
T1.NPV_CNY AS MTM, T1.CURRENCY_CODE AS MTM_CCY, T.NOTIONAL, COALESCE(T2.BOND_RATING,'Unrated') AS SUBCLASS, T.CURRENCY_CODE AS NOTIONAL_CCY, T3.MA_ID
FROM TB_13_CDS_ALL T
LEFT JOIN TB_26_TRADE_MEASURE T1 ON T1.INSTRUMENT_ID = T.INSTRUMENT_ID AND T1.DATA_DATE = #{dataDate,jdbcType=DATE}
LEFT JOIN TB_13_BOND_BASIC_INFO T2 ON T2.BOND_ID = T.UNDERLYING_BOND_ID AND T2.DATA_DATE = #{dataDate,jdbcType=DATE}
LEFT JOIN TB_17_SACCR_MA_CSA T3 ON T3.COUNTERPARTY_CODE=T.COUNTERPARTY_CODE AND T3.DATA_DATE = #{dataDate,jdbcType=DATE}
WHERE  T.MATURITY_DATE > #{dataDate,jdbcType=DATE}

SELECT T.DEALID, T.COUNTERPARTY_CODE, T.GUARANTEE_AMOUNT, T.GUARANTEE_CURRENCY, 'CNY' AS CSA_SETTLEMENT_CCY_y, 0 AS COL_HAIRCUT_y
FROM TB_13_GUARANTEE_DK T
WHERE T.DATA_DATE = #{dataDate,jdbcType=DATE}
